import SwiftUI

/// Semantic colour tokens (spec 7.2), backed by the asset catalog with light, dark and
/// Increase Contrast versions. Generated by `scripts/gen_colors.py`.
/// Feature code uses these and never raw hex values.
struct SWColors: Sendable {
  let background = Color("Colors/background")
  let backgroundGrouped = Color("Colors/backgroundGrouped")
  let card = Color("Colors/card")
  let fill = Color("Colors/fill")
  let fill2 = Color("Colors/fill2")
  let label = Color("Colors/label")
  let labelSecondary = Color("Colors/labelSecondary")
  /// Decoration only: chevrons, the "?" ring, placeholders. Never meaningful text.
  let labelTertiary = Color("Colors/labelTertiary")
  let separator = Color("Colors/separator")
  /// Book tickets, Best pick, the selected row, kickers. Nothing else is red.
  let accent = Color("Colors/accent")
  let onAccent = Color("Colors/onAccent")
  let accentSoft = Color("Colors/accentSoft")
  let glassFallback = Color("Colors/glassFallback")
  let stageCenter = Color("Colors/stageCenter")
  let stageMid = Color("Colors/stageMid")
  let stageEdge = Color("Colors/stageEdge")
  /// The "In cinemas" dot.
  let success = Color.green
}

extension Color {
  static let sw = SWColors()
}

/// Corner radii (spec 7.5).
enum Radius {
  static let carouselCard: CGFloat = 28
  static let sheetTop: CGFloat = 28
  static let theatreImage: CGFloat = 22
  static let scoreBox: CGFloat = 18
  static let grouped: CGFloat = 16
  static let iconTile: CGFloat = 12
  static let button: CGFloat = 14
  static let thumbnail: CGFloat = 10
}

/// Spacing on a 4 pt grid (spec 7.5).
enum Spacing {
  static let margin: CGFloat = 20
  static let barMargin: CGFloat = 16
  static let section: CGFloat = 24
  static let minHit: CGFloat = 44
}

/// Springs (spec 7.7).
enum Motion {
  static let push = Animation.smooth(duration: 0.42)
  static let select = Animation.snappy(duration: 0.25)
}

extension View {
  /// `shadowCard` in light mode. Dark mode relies on fill contrast.
  func swShadowCard() -> some View { modifier(ShadowModifier(kind: .card)) }
  /// `shadowSmall` in light mode.
  func swShadowSmall() -> some View { modifier(ShadowModifier(kind: .small)) }
}

private struct ShadowModifier: ViewModifier {
  enum Kind { case card, small }
  let kind: Kind
  @Environment(\.colorScheme) private var scheme

  func body(content: Content) -> some View {
    if scheme == .dark {
      content.shadow(color: .black.opacity(kind == .card ? 0.35 : 0.25), radius: 12, y: 6)
    } else if kind == .card {
      content
        .shadow(color: .black.opacity(0.05), radius: 1, y: 1)
        .shadow(color: .black.opacity(0.07), radius: 8, y: 6)
        .shadow(color: .black.opacity(0.06), radius: 20, y: 18)
    } else {
      content
        .shadow(color: .black.opacity(0.06), radius: 1, y: 1)
        .shadow(color: .black.opacity(0.06), radius: 6, y: 4)
    }
  }
}

extension Color {
  /// Parses "#RRGGBB". Only for data colours such as a movie's tint, never for UI tokens.
  init?(hex: String?) {
    guard var s = hex?.trimmingCharacters(in: .whitespaces) else { return nil }
    if s.hasPrefix("#") { s.removeFirst() }
    guard s.count == 6, let v = UInt32(s, radix: 16) else { return nil }
    self.init(
      .sRGB, red: Double((v >> 16) & 0xFF) / 255, green: Double((v >> 8) & 0xFF) / 255,
      blue: Double(v & 0xFF) / 255)
  }
}
